/* =====================================================================
   Salt / Generic Master - OLD data copy - 2026-11-13
   Source : OLD HIS DEMO_HIS_NEW.dbo.SaltNameMaster (3,520 rows, exported 2026-11-13)
   Target : GWT_HIS_API.dbo.SaltNameMaster (already holds 52 of these with the same ids and names)
   Run AFTER 2026-11-13_SaltNameMaster.sql. Re-runnable: inserts only ids that are not present yet.
   OLD ids are kept (IDENTITY_INSERT) so that OLD store items (ServiceItemMaster.DescriptionId) map without remapping
   (owner decision 2026-11-13, Store_Item_Master_Build_Spec 6.5).
   OLD ids 1099 and 2696 contain a corrupt character (U+FFFD) in OLD; it is copied as "?".
   Known OLD data: non-salt groupings (SURG, LAB-KITS, GRAL, ...), a salt named "NULL", many names with strength.
   CreatedBy / LastModifiedBy are OLD user ids, copied as they are.
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

IF OBJECT_ID('tempdb..#salt') IS NOT NULL DROP TABLE #salt;
CREATE TABLE #salt (HospId int, SaltNameId int, SaltName nvarchar(256), IsActive int, CreatedBy int, CreatedOn datetime,
                    LastModifiedBy int, LastModifiedOn datetime, IpAddress nvarchar(20), UniqueId nvarchar(50));


SET IDENTITY_INSERT dbo.SaltNameMaster ON;
SELECT s.HospId, s.SaltNameId, s.SaltName, s.IsActive, s.CreatedBy, s.CreatedOn, s.LastModifiedBy, s.LastModifiedOn, s.IpAddress, s.UniqueId
FROM #salt s
WHERE NOT EXISTS (SELECT 1 FROM dbo.SaltNameMaster t WHERE t.SaltNameId = s.SaltNameId);
PRINT CAST(@@ROWCOUNT AS varchar) + ' salt(s) copied.';
SET IDENTITY_INSERT dbo.SaltNameMaster OFF;

-- keep the identity seed above the highest copied id
DECLARE @maxId int = (SELECT ISNULL(MAX(SaltNameId), 0) FROM dbo.SaltNameMaster);
DBCC CHECKIDENT ('dbo.SaltNameMaster', RESEED, @maxId) WITH NO_INFOMSGS;

-- names that differ only by spaces/case (the unique-name rule will block editing one of each pair; merge later)
SELECT LTRIM(RTRIM(SaltName)) AS DuplicateName, COUNT(*) AS Cnt, STRING_AGG(CAST(SaltNameId AS varchar), ',') AS Ids
FROM dbo.SaltNameMaster GROUP BY LTRIM(RTRIM(SaltName)) HAVING COUNT(*) > 1;

DROP TABLE #salt;
COMMIT;
GO
